/**
 * The shelf of family games. This registry is shared. Game screens live in
 * `src/games/` and are not edited from the landing lane.
 *
 * Each file in `./entries` is one game. Add a game by creating
 * `src/lib/games/entries/<id>.ts` — do not edit this file.
 * The module default-exports a `GameEntry`, or exports it as `entry`.
 * Its `load` import points at that game's screen.
 *
 * Word Search is `src/lib/games/entries/word-search.ts`.
 * That file can be added or replaced without changing this registry.
 */
import { collectGames, gameForPath as findGame, type EntryModule } from './list';
import type { GameEntry } from './types';

const modules = import.meta.glob('./entries/*.ts', { eager: true }) as Record<string, EntryModule>;

export const games: GameEntry[] = collectGames(modules);

export function gameForPath(path: string): GameEntry | undefined {
  return findGame(games, path);
}
